def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    opp_c = 0
    for me, opp in history:
        if opp == 'C':
            opp_c += 1
    opp_d = n - opp_c

    if opp_d == 0:
        return 'C'
    if opp_c == 0:
        return 'D'

    last_me, last_opp = history[-1]

    window = min(10, n)
    recent_opp_c = 0
    for me, opp in history[-window:]:
        if opp == 'C':
            recent_opp_c += 1

    if recent_opp_c >= window - 1:
        if last_opp == 'D':
            if n >= 2 and history[-2][1] == 'C':
                return 'C'
            return 'D'
        return 'C'

    recent_opp_d = window - recent_opp_c
    if recent_opp_d >= window - 1:
        if last_me == 'D' and last_opp == 'D' and opp_c > 0:
            return 'C'
        return 'D' if last_opp == 'D' else 'C'

    if last_opp == 'C':
        if n > 90 and rng.random() < 0.2:
            return 'D'
        return 'C'
    else:
        if last_me == 'D':
            if opp_c > 0:
                return 'C'
            return 'D'
        else:
            if opp_c >= 2 and rng.random() < 0.15:
                return 'C'
            return 'D'
